overrides.style:
Menu, Dropdown, Popup, Dialog { border-radius: 14px; border: 1px solid var(--accent-soft); }
Sheet { border-radius: 20px 20px 0 0; border: 1px solid var(--accent-soft); }
SearchField#chats, SearchField#icons, TextField, Composer::field { border-radius: 12px; }
Fab { border-radius: 9px; }
IconTile[icon="theme"], IconTile[icon="store"] { border-radius: 9px; background: var(--accent-soft); color: var(--ink); }
